// ==UserScript==
// @name BULL TRADER LLC BOT - LICENSED
// @namespace bull-trader-llc
// @version 4.0.0
// @description BULL TRADER LLC - RANDOM UP/DOWN 3SEC - CENTRAL LICENSE + 7 DAY DEVICE VERIFY
// @match https://market-qx.trade/*
// @match https://*.market-qx.trade/*
// @run-at document-idle
// @grant none
// ==/UserScript==

(function () {
    'use strict';
    if (window.__BULL_TRADER_LLC_BOT__) return;
    window.__BULL_TRADER_LLC_BOT__ = true;

    // =========================================================
    // CENTRAL LICENSE CONFIG
    // =========================================================
    // Put a JSON file at this URL. Example:
    // {"license":"bulltraderllc098","version":"1"}
    //
    // Change the license OR version in that file and every device
    // will require verification again after its next config check.
    const LICENSE_CONFIG_URL =
        "https://raw.githubusercontent.com/YOUR-GITHUB-USER/YOUR-REPO/main/license.json";

    // Used only if the central config cannot be reached.
    // For true central control, replace the URL above with your real
    // GitHub raw JSON / API endpoint and keep this fallback unused.
    const FALLBACK_LICENSE = "bulltraderllc098";

    const BOT_LOGO_URL = "data:image/jpeg;base64,";

    const WAIT_MS = 3000;
    const VERIFY_CACHE_MS = 7 * 24 * 60 * 60 * 1000;

    const STORAGE = {
        LICENSE: 'BULL_LLC_LICENSE',
        LICENSE_VERSION: 'BULL_LLC_LICENSE_VERSION',
        VERIFIED_AT: 'BULL_LLC_VERIFIED_AT'
    };

    let currentLicense = null;
    let currentLicenseVersion = null;
    let isLicensed = false;
    let running = false;
    let timer = null;
    let panel = null;

    function getSavedLicense() {
        return {
            license: localStorage.getItem(STORAGE.LICENSE),
            version: localStorage.getItem(STORAGE.LICENSE_VERSION),
            verifiedAt: Number(localStorage.getItem(STORAGE.VERIFIED_AT) || 0)
        };
    }

    function clearSavedLicense() {
        localStorage.removeItem(STORAGE.LICENSE);
        localStorage.removeItem(STORAGE.LICENSE_VERSION);
        localStorage.removeItem(STORAGE.VERIFIED_AT);
        isLicensed = false;
    }

    async function loadLicenseConfig() {
        try {
            const response = await fetch(LICENSE_CONFIG_URL + '?t=' + Date.now(), {
                cache: 'no-store',
                credentials: 'omit'
            });

            if (!response.ok) throw new Error('License server HTTP ' + response.status);

            const config = await response.json();

            if (!config || typeof config.license !== 'string' || !config.license.trim()) {
                throw new Error('Invalid license config');
            }

            currentLicense = config.license.trim();
            currentLicenseVersion = String(config.version ?? '1');
            return true;
        } catch (error) {
            // If the URL is still the placeholder, use the fallback.
            // Once a real URL is configured, you can remove this fallback
            // to make the system fail closed when the server is unavailable.
            if (LICENSE_CONFIG_URL.includes('YOUR-GITHUB-USER/YOUR-REPO')) {
                currentLicense = FALLBACK_LICENSE;
                currentLicenseVersion = 'fallback';
                return true;
            }

            update('LICENSE SERVER ERROR', '#ef4444');
            return false;
        }
    }

    function isSavedVerificationValid() {
        if (!currentLicense || !currentLicenseVersion) return false;

        const saved = getSavedLicense();
        if (!saved.license || !saved.verifiedAt) return false;

        // A license/version change invalidates every old device cache.
        if (saved.license !== currentLicense) return false;
        if (saved.version !== currentLicenseVersion) return false;

        return (Date.now() - saved.verifiedAt) < VERIFY_CACHE_MS;
    }

    function applyVerifiedUI() {
        isLicensed = true;

        const licenseSection = panel?.querySelector('#bull-license-section');
        const status = panel?.querySelector('#bull-status');
        const startBtn = panel?.querySelector('#bull-start');

        if (licenseSection) licenseSection.style.display = 'none';
        if (status) status.style.display = 'none';

        if (startBtn) {
            startBtn.disabled = false;
            startBtn.style.opacity = '1';
        }

        update('READY', '#22c55e');
    }

    function verifyLicense(inputKey) {
        if (!currentLicense || inputKey !== currentLicense) {
            update('INVALID LICENSE!', '#ef4444');
            return false;
        }

        localStorage.setItem(STORAGE.LICENSE, currentLicense);
        localStorage.setItem(STORAGE.LICENSE_VERSION, currentLicenseVersion);
        localStorage.setItem(STORAGE.VERIFIED_AT, String(Date.now()));

        isLicensed = true;
        applyVerifiedUI();
        return true;
    }

    function update(status, color = null) {
        if (!panel) return;
        const el = panel.querySelector('#bull-status');
        if (!el) return;
        el.textContent = status;
        el.style.color = color || (running ? '#22c55e' : '#9ca3af');
    }

    function findButtons() {
        const els = document.querySelectorAll('button,[role="button"],a,div');
        let upBtn = null, downBtn = null;

        for (const el of els) {
            const text = (
                el.getAttribute('aria-label') ||
                el.textContent ||
                ''
            ).trim().toLowerCase();

            const r = el.getBoundingClientRect();
            if (r.width < 40 || r.height < 25 || r.bottom < 0 || r.top > innerHeight) continue;

            if (text === 'up' || text === 'higher' || text === 'buy') {
                upBtn = el.closest('button,[role="button"]') || el;
            }

            if (text === 'down' || text === 'lower' || text === 'sell') {
                downBtn = el.closest('button,[role="button"]') || el;
            }
        }

        if (!upBtn || !downBtn) {
            for (const el of els) {
                const r = el.getBoundingClientRect();

                if (
                    r.width < 60 || r.height < 35 ||
                    r.width > 500 || r.height > 250 ||
                    r.bottom < 0 || r.top > innerHeight
                ) continue;

                let bg;
                try {
                    bg = getComputedStyle(el).backgroundColor;
                } catch (_) {
                    continue;
                }

                const m = bg.match(/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/);
                if (!m) continue;

                const R = +m[1], G = +m[2], B = +m[3];

                if (!downBtn && R > 140 && R > G * 1.25 && R > B * 1.15) {
                    downBtn = el;
                }

                if (!upBtn && G > 100 && G > R * 1.1) {
                    upBtn = el;
                }
            }
        }

        return { upBtn, downBtn };
    }

    function start() {
        if (!isLicensed) {
            update('ENTER VALID LICENSE!', '#ef4444');
            return;
        }

        if (running) return;

        running = true;
        update('WAITING 3s...', '#22c55e');

        timer = setTimeout(() => {
            timer = null;

            if (!running) return;

            const { upBtn, downBtn } = findButtons();

            if (!upBtn && !downBtn) {
                running = false;
                update('BUTTONS NOT FOUND', '#ef4444');
                return;
            }

            const isUp = Math.random() < 0.5;
            const targetBtn = isUp ? upBtn : downBtn;
            const tradeType = isUp ? 'UP' : 'DOWN';

            if (!targetBtn) {
                running = false;
                update(`${tradeType} NOT FOUND`, '#ef4444');
                return;
            }

            try {
                targetBtn.click();
                update(`${tradeType} CLICKED`, isUp ? '#22c55e' : '#ef4444');
            } catch (_) {
                update('CLICK ERROR', '#ef4444');
            }

            running = false;
        }, WAIT_MS);
    }

    function stop() {
        running = false;

        if (timer) {
            clearTimeout(timer);
            timer = null;
        }

        update('STOPPED');
    }

    function makeDraggable() {
        const handle = panel.querySelector('#bull-drag-handle');
        if (!handle) return;

        let dragging = false;
        let offsetX = 0;
        let offsetY = 0;

        handle.style.touchAction = 'none';
        handle.style.cursor = 'move';

        handle.addEventListener('pointerdown', (event) => {
            if (event.button !== undefined && event.button !== 0) return;

            const rect = panel.getBoundingClientRect();

            dragging = true;
            offsetX = event.clientX - rect.left;
            offsetY = event.clientY - rect.top;

            panel.style.left = rect.left + 'px';
            panel.style.top = rect.top + 'px';
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';

            try {
                handle.setPointerCapture(event.pointerId);
            } catch (_) {}
        });

        handle.addEventListener('pointermove', (event) => {
            if (!dragging) return;

            let left = event.clientX - offsetX;
            let top = event.clientY - offsetY;

            const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth);
            const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight);

            left = Math.max(0, Math.min(left, maxLeft));
            top = Math.max(0, Math.min(top, maxTop));

            panel.style.left = left + 'px';
            panel.style.top = top + 'px';
        });

        const stopDrag = (event) => {
            if (!dragging) return;
            dragging = false;

            try {
                handle.releasePointerCapture(event.pointerId);
            } catch (_) {}
        };

        handle.addEventListener('pointerup', stopDrag);
        handle.addEventListener('pointercancel', stopDrag);
    }

    function createUI() {
        panel = document.createElement('div');

        panel.style.cssText = `
            position:fixed;
            top:70px;
            left:10px;
            width:250px;
            max-width:calc(100vw - 20px);
            z-index:2147483647;
            background:#111827;
            color:white;
            border:1px solid #D4AF37;
            border-radius:12px;
            box-shadow:0 8px 25px rgba(0,0,0,.5);
            font-family:Arial,sans-serif;
            overflow:hidden;
            box-sizing:border-box;
        `;

        panel.innerHTML = `
            <div
                id="bull-drag-handle"
                style="
                    padding:12px;
                    background:linear-gradient(90deg,#111827,#1f2937);
                    font-weight:bold;
                    text-align:center;
                    font-size:14px;
                    border-bottom:1px solid #D4AF37;
                    user-select:none;
                    -webkit-user-select:none;
                "
            >
                <img
                    src="${BOT_LOGO_URL}"
                    onerror="this.style.display='none'"
                    style="
                        width:45px;
                        height:45px;
                        object-fit:cover;
                        border-radius:8px;
                        margin-bottom:5px;
                        display:block;
                        margin-left:auto;
                        margin-right:auto;
                    "
                />
                🐂 BULL TRADER LLC<br>
                <span style="font-size:9px;color:#facc15;font-weight:normal;">
                    LICENSED BOT v4.0
                </span>
            </div>

            <div id="bull-license-section" style="padding:12px;text-align:center;">
                <input
                    id="license-input"
                    type="password"
                    placeholder="Enter License Key"
                    style="
                        width:100%;
                        box-sizing:border-box;
                        padding:8px;
                        border-radius:6px;
                        border:1px solid #374151;
                        background:#1f2937;
                        color:white;
                        margin-bottom:8px;
                        text-align:center;
                    "
                />

                <button
                    id="license-verify"
                    style="
                        width:100%;
                        padding:8px;
                        border:0;
                        border-radius:6px;
                        background:#D4AF37;
                        color:black;
                        font-weight:bold;
                        margin-bottom:10px;
                    "
                >
                    VERIFY LICENSE
                </button>
            </div>

            <div style="padding:12px;text-align:center;">
                <div
                    id="bull-status"
                    style="
                        font-weight:bold;
                        margin-bottom:10px;
                        color:#9ca3af;
                        font-size:12px;
                    "
                >
                    LICENSE REQUIRED
                </div>

                <button
                    id="bull-start"
                    disabled
                    style="
                        width:100%;
                        padding:10px;
                        border:0;
                        border-radius:7px;
                        background:#16a34a;
                        color:white;
                        font-weight:bold;
                        opacity:0.5;
                    "
                >
                    START
                </button>

                <button
                    id="bull-stop"
                    style="
                        width:100%;
                        margin-top:7px;
                        padding:10px;
                        border:0;
                        border-radius:7px;
                        background:#dc2626;
                        color:white;
                        font-weight:bold;
                    "
                >
                    STOP
                </button>
            </div>
        `;

        document.body.appendChild(panel);

        const licenseInput = panel.querySelector('#license-input');
        const verifyBtn = panel.querySelector('#license-verify');

        verifyBtn.onclick = () => {
            verifyLicense(licenseInput.value.trim());
        };

        panel.querySelector('#bull-start').onclick = start;
        panel.querySelector('#bull-stop').onclick = stop;

        makeDraggable();
    }

    function forceRelock() {
        stop();
        clearSavedLicense();

        const licenseSection = panel?.querySelector('#bull-license-section');
        const status = panel?.querySelector('#bull-status');
        const startBtn = panel?.querySelector('#bull-start');
        const licenseInput = panel?.querySelector('#license-input');
        const verifyBtn = panel?.querySelector('#license-verify');

        if (licenseSection) licenseSection.style.display = 'block';
        if (status) status.style.display = 'block';

        if (startBtn) {
            startBtn.disabled = true;
            startBtn.style.opacity = '0.5';
        }

        if (licenseInput) {
            licenseInput.value = '';
            licenseInput.disabled = false;
        }

        if (verifyBtn) {
            verifyBtn.textContent = 'VERIFY LICENSE';
            verifyBtn.style.background = '#D4AF37';
        }

        update('LICENSE CHANGED — VERIFY AGAIN', '#ef4444');
    }

    async function refreshCentralLicense() {
        const oldLicense = currentLicense;
        const oldVersion = currentLicenseVersion;

        const ok = await loadLicenseConfig();
        if (!ok) return;

        if (
            oldLicense !== null &&
            (oldLicense !== currentLicense || oldVersion !== currentLicenseVersion)
        ) {
            forceRelock();
            return;
        }

        // If the page was open for more than 7 days, require verification.
        if (isLicensed && !isSavedVerificationValid()) {
            forceRelock();
        }
    }

    async function boot() {
        if (!document.body) {
            setTimeout(boot, 100);
            return;
        }

        createUI();

        const configLoaded = await loadLicenseConfig();
        if (!configLoaded) return;

        // Auto-login for this device for 7 days.
        // A central license/version change invalidates the saved verification.
        if (isSavedVerificationValid()) {
            applyVerifiedUI();
        } else {
            clearSavedLicense();
            update('LICENSE REQUIRED', '#9ca3af');
        }

        // Check the central license periodically so a license change
        // can lock already-open devices without waiting for a reload.
        setInterval(refreshCentralLicense, 60 * 1000);
    }

    boot();
})();
